export function pad(n: number): string {
  return String(n).padStart(2, '0');
}

export function todayStr(d = new Date()): string {
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

export function addDays(dateStr: string, days: number): string {
  const d = new Date(dateStr + 'T00:00:00');
  d.setDate(d.getDate() + days);
  return todayStr(d);
}

const WOCHENTAGE = ['Sonntag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag', 'Sonntag'];
// Hinweis: getUTCDay/Date-Wochentag wird unten korrekt über getDay aufgelöst.
const TAGESNAMEN = ['Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa', 'So'];

const MONATE = [
  'Januar',
  'Februar',
  'März',
  'April',
  'Mai',
  'Juni',
  'Juli',
  'August',
  'September',
  'Oktober',
  'November',
  'Dezember',
];

export function formatGermanDate(dateStr: string): string {
  const d = new Date(dateStr + 'T00:00:00');
  const wochentag = WOCHENTAGE[d.getDay()] ?? '';
  const tag = d.getDate();
  const monat = MONATE[d.getMonth()] ?? '';
  const jahr = d.getFullYear();
  const heute = todayStr();
  if (dateStr === heute) {
    return `Heute · ${wochentag}, ${tag}. ${monat} ${jahr}`;
  }
  return `${wochentag}, ${tag}. ${monat} ${jahr}`;
}

export function last7Days(): string[] {
  const out: string[] = [];
  const today = new Date();
  for (let i = 6; i >= 0; i--) {
    const cursor = new Date(today);
    cursor.setDate(cursor.getDate() - i);
    out.push(todayStr(cursor));
  }
  return out;
}

export function shortDayLabel(dateStr: string): string {
  const d = new Date(dateStr + 'T00:00:00');
  return `${TAGESNAMEN[d.getDay()]} ${d.getDate()}`;
}

export interface Streaks {
  current: number;
  longest: number;
}

export function computeStreaks(completedDates: string[]): Streaks {
  const set = new Set(completedDates);
  const heute = todayStr();

  // Aktuelle Serie: lückelose Kette bis heute (oder bis gestern, wenn heute noch offen).
  let current = 0;
  let cursor = new Date(heute + 'T00:00:00');
  if (!set.has(heute)) {
    cursor.setDate(cursor.getDate() - 1);
  }
  while (set.has(todayStr(cursor))) {
    current += 1;
    cursor.setDate(cursor.getDate() - 1);
  }

  // Längste Serie je zuvor abgeschlossener Kette.
  const sorted = [...set].sort();
  let longest = 0;
  let run = 0;
  let prev: string | null = null;
  for (const day of sorted) {
    if (prev !== null && addDays(prev, 1) === day) {
      run += 1;
    } else {
      run = 1;
    }
    longest = Math.max(longest, run);
    prev = day;
  }

  return { current, longest };
}

